SET body = '<!DOCTYPE html><html><body style="margin:0;padding:0;background-color:#f4f4f4;font-family:Arial,Helvetica,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f4f4;padding:24px 0;"><tr><td align="center"><table role="presentation" width="480" cellpadding="0" cellspacing="0" style="background-color:#ffffff;border-radius:8px;overflow:hidden;"><tr><td style="background-color:#2e7d32;padding:20px 24px;"><span style="color:#ffffff;font-size:20px;font-weight:bold;">Farm2Home Milk</span></td></tr><tr><td style="padding:32px 24px;color:#333333;"><p style="font-size:18px;margin:0 0 16px;">Out for Delivery</p><p style="font-size:15px;line-height:1.5;margin:0 0 20px;">Dear {{customer_name}}, your order #{{order_number}} is out for delivery with {{partner_name}}.</p><table role="presentation" width="100%" cellpadding="8" cellspacing="0" style="border-collapse:collapse;margin:0 0 20px;background-color:#f1f8f2;border-radius:6px;"><tr><td style="padding:12px;color:#777777;font-size:13px;">Expected Delivery</td><td style="padding:12px;text-align:right;font-weight:bold;font-size:14px;">{{expected_time}}</td></tr></table><p style="font-size:14px;line-height:1.5;margin:0;color:#555555;">You will be notified as soon as your order is delivered.</p></td></tr><tr><td style="padding:16px 24px;background-color:#fafafa;text-align:center;"><span style="font-size:12px;color:#999999;">This is an automated message from Farm2Home Milk. Please do not reply.</span></td></tr></table></td></tr></table></body></html>'
