SET body = '<!DOCTYPE html><html><body style="margin:0;padding:0;background-color:#f4f4f4;font-family:Arial,Helvetica,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f4f4;padding:24px 0;"><tr><td align="center"><table role="presentation" width="480" cellpadding="0" cellspacing="0" style="background-color:#ffffff;border-radius:8px;overflow:hidden;"><tr><td style="background-color:#e65100;padding:20px 24px;"><span style="color:#ffffff;font-size:20px;font-weight:bold;">Farm2Home Milk</span></td></tr><tr><td style="padding:32px 24px;color:#333333;"><p style="font-size:18px;margin:0 0 16px;">Delivery Unsuccessful</p><p style="font-size:15px;line-height:1.5;margin:0 0 16px;">Dear {{customer_name}}, we were unable to deliver your order #{{order_number}}.</p><table role="presentation" width="100%" cellpadding="8" cellspacing="0" style="border-collapse:collapse;margin:0 0 20px;background-color:#fff8f1;border-radius:6px;"><tr><td style="padding:12px;color:#777777;font-size:13px;">Reason</td><td style="padding:12px;text-align:right;font-weight:bold;font-size:14px;">{{reason}}</td></tr></table><p style="font-size:14px;line-height:1.5;margin:0;color:#555555;">Our team will reach out shortly to reschedule your delivery.</p></td></tr><tr><td style="padding:16px 24px;background-color:#fafafa;text-align:center;"><span style="font-size:12px;color:#999999;">This is an automated message from Farm2Home Milk. Please do not reply.</span></td></tr></table></td></tr></table></body></html>'
